"""Complete 28 immunology and treatment-safety questions."""
from create_rheum_immunology import rows,q,CO,HA,ref
from qbank_authoring import finalize
VA=ref('ACR vaccination guideline: 2022','https://pmc.ncbi.nlm.nih.gov/articles/PMC10291822/')
IN=ref('EULAR opportunistic/chronic infection screening and prophylaxis','https://doi.org/10.1136/ard-2022-223335')
DM=ref('BSR conventional DMARD prescribing/monitoring guideline: 2025','https://doi.org/10.1093/rheumatology/keaf522')

q('A patient is about to begin substantial immunosuppression and lacks measles immunity. Which principle should guide MMR vaccination?', 'Give a live vaccine before treatment when appropriate and allow the recommended interval, rather than administer routinely during substantial immunosuppression',[
 ('MMR is a nonlive vaccine and can always be given during any regimen','MMR is live attenuated.'),('Every vaccine must be avoided permanently once autoimmune disease is diagnosed','Many nonlive vaccines remain recommended.'),('Use antibody-negative status alone to ignore the immune regimen','The degree and timing of immunosuppression affect live-vaccine safety.')],
 'Distinguish live-vaccine safety from nonlive-vaccine effectiveness','**Live attenuated vaccines can cause disease in significantly immunocompromised hosts.**',['Timing depends on the drug, dose and urgency of disease treatment.','A common pre-treatment interval is at least four weeks for live vaccines when feasible, subject to the specific guidance.'], '**Plan vaccination early rather than discover the gap after therapy starts.**',['Do not delay urgent life-saving immune treatment without a reasoned plan.','Coordinate with the treating team when a medication interruption is considered.'],[['Live vaccine','Safety/timing constraints'],['Nonlive vaccine','Usually safe, response may be reduced'],['Planning','Before treatment when feasible']],[VA],style='clinical_scenario')

q('Why is timing of nonlive vaccination around rituximab important?', 'B-cell depletion can reduce antibody responses, so vaccination before depletion or toward B-cell recovery can improve immunogenicity',[
 ('All nonlive vaccines become live after rituximab','The vaccine type does not change.'),('Rituximab invariably causes a fatal vaccine infection from inactivated influenza vaccine','Nonlive vaccines do not have that replication mechanism.'),('The timing matters only for injection-site pain','The central issue is immune response.')],
 'A safe vaccine can still have reduced effectiveness','**Rituximab can markedly attenuate humoral vaccine responses.**',['ACR gives specific timing advice for vaccines other than seasonal influenza around the next rituximab dose.','Influenza vaccination should not simply be missed while waiting for an ideal interval.'], '**Coordinate disease control and vaccination rather than applying a blanket prohibition.**',['When disease activity allows, delay subsequent rituximab after vaccination according to guidance.','Explain that vaccination does not guarantee a normal antibody response.'],[['Nonlive vaccine','Generally safe'],['B-cell depletion','Reduced response'],['Influenza','Avoid missing the seasonal opportunity']],[VA])

q('Before potent immunosuppression, which hepatitis B screening panel most directly distinguishes current infection, prior exposure and immunity?', 'HBsAg, total anti-HBc and anti-HBs',[
 ('HBsAg alone','This can miss prior infection relevant to reactivation.'),('Anti-HBs alone','This does not adequately establish current or prior infection.'),('ALT alone','Normal liver enzymes do not exclude HBV infection or reactivation risk.')],
 'Screen for the state that treatment can reactivate','**A complete HBV serological panel informs risk-based prophylaxis and monitoring.**',['Anti-HBc identifies prior exposure even when HBsAg is negative.','HBV DNA assessment and hepatology input depend on the findings and planned regimen.'], '**Do not assume vaccination or normal ALT answers every HBV question.**',['B-cell-depleting therapy is a particularly important reactivation setting.','Plan prevention before the first dose.'],[['HBsAg','Current infection marker'],['Anti-HBc','Prior/current exposure'],['Anti-HBs','Immunity context']],[IN])

q('A patient will receive prolonged high-dose glucocorticoids plus another potent immunosuppressant. What should guide PJP prophylaxis?', 'Assess regimen, dose/duration and host risk rather than use an autoimmune diagnosis alone as the indication',[
 ('Never give prophylaxis outside HIV','PJP occurs in other immunocompromised populations.'),('Give lifelong prophylaxis to every patient with any positive ANA','This exposes low-risk patients to unnecessary toxicity.'),('Use CD4 count as the only validated rule for every rheumatic disease regimen','Non-HIV risk does not map perfectly to the HIV threshold.')],
 'Estimate risk from the treatment and host','**PJP prevention is relevant to selected high-risk rheumatological regimens.**',['Glucocorticoid dose/duration, combination treatment, lung disease, lymphopenia and age can matter.','The exact decision follows the disease/regimen guidance and individual factors.'], '**Review prophylaxis safety and stopping criteria.**',['TMP-SMX requires renal, potassium, marrow and interaction review.','Alternative drugs have their own limitations.'],[['Treatment intensity','Key risk determinant'],['Host factors','Modify risk'],['Prophylaxis','Benefits and adverse effects must be weighed']],[IN],style='clinical_scenario')

q('A patient needs dapsone as an alternative PJP preventive agent. Which test is particularly important beforehand?', 'G6PD assessment',[
 ('HLA-B*58:01 alone','This is an allopurinol hypersensitivity association, not the defining dapsone screen.'),('Anti-CCP','This does not assess oxidant hemolysis risk.'),('A serum ACE level','This does not determine dapsone safety.')],
 'Oxidant toxicity is central to dapsone safety','**Dapsone can cause hemolysis and methemoglobinemia.**',['G6PD deficiency increases hemolysis concern.','A normal G6PD result does not eliminate every adverse effect.'], '**Review blood counts, symptoms and oxygenation when indicated.**',['Unexplained cyanosis or a saturation gap warrants methemoglobin assessment.','Choice of preventive agent also depends on the infection being prevented and any additional coverage needed.'],[['G6PD','Oxidant hemolysis risk'],['Methemoglobinemia','Can cause cyanosis/saturation gap'],['Monitoring','Clinical and laboratory safety']],[ref('NIH adult opportunistic infection guideline: Pneumocystis','https://clinicalinfo.hiv.gov/en/guidelines/hiv-clinical-guidelines-adult-and-adolescent-opportunistic-infections/pneumocystis')])

q('Which pre-existing neurological condition should particularly influence a decision to start a TNF inhibitor?', 'Demyelinating disease',[
 ('Stable presbyopia','This is not the defining neurological contraindication concern.'),('A remote uncomplicated tension headache','This does not carry the same mechanistic safety concern.'),('An isolated uncomplicated ankle sprain','This is not relevant to demyelination risk.')],
 'A biologic target can have organ-specific safety constraints','**TNF inhibitors can be associated with new or worsening demyelinating disease.**',['Significant heart failure and serious infection are other important considerations.','The exact choice depends on the disease and available alternatives.'], '**Review neurological history before treatment.**',['Investigate new focal neurological symptoms rather than attribute them to the autoimmune disease automatically.','Use a suitable alternative mechanism when the risk profile warrants it.'],[['Demyelination','TNF safety concern'],['Serious infection','Another key concern'],['Alternative pathway','May be preferable']],[ref('FDA Humira prescribing information','https://www.rxabbvie.com/pdf/humira.pdf')])

q('A patient on a TNF inhibitor returns from an endemic area with fever, weight loss, pulmonary disease and disseminated fungal infection concern. Which pathogen is particularly relevant?', 'Histoplasma capsulatum',[
 ('Rhinovirus as the only plausible opportunistic cause','The systemic disseminated phenotype requires a broader differential.'),('A superficial dermatophyte as the sole explanation','This does not best explain disseminated pulmonary/systemic illness.'),('Malassezia as the defining endemic granulomatous pathogen','Histoplasma is a classic endemic opportunistic concern in this context.')],
 'TNF is important for granulomatous host defense','**TNF blockade increases concern for TB and invasive endemic fungal infection.**',['Travel, residence and exposure history guide testing.','Antigen, culture and tissue may be useful depending on the syndrome.'], '**Assess illness severity and review immune therapy during infection.**',['Do not label fever and pulmonary lesions as an autoimmune flare without evaluating infection.','Use infectious disease input for a possible disseminated mycosis.'],[['Exposure history','Essential context'],['TNF blockade','Granulomatous defense impairment'],['Testing','Syndrome-directed microbiology']],[ref('FDA Humira infection warnings','https://www.rxabbvie.com/pdf/humira.pdf')],style='clinical_scenario')

q('Which infection susceptibility is mechanistically associated with IL-17 pathway inhibition?', 'Mucocutaneous Candida infection',[
 ('Neisseria infection uniquely caused by terminal complement blockade','That association more directly reflects a different immune pathway.'),('Enteroviral infection from absent B cells as the defining mechanism','This is not the characteristic IL-17 effect.'),('No fungal susceptibility because the drug is targeted','Targeted immune pathways can have specific host-defense roles.')],
 'IL-17 contributes to mucosal antifungal defense','**IL-17 inhibition can increase mucocutaneous Candida risk.**',['This does not mean every patient develops invasive fungal disease.','Review active infection and other immune risks before treatment.'], '**Recognize symptoms early and treat appropriately.**',['Assess IBD history because it also affects IL-17 drug selection.','Do not assume every sore mouth is autoimmune mucositis.'],[['IL-17','Mucosal Candida defense'],['Clinical monitoring','Thrush and other mucosal symptoms'],['Selection','Include IBD and infection history']],[ref('FDA Cosentyx prescribing information','https://www.novartis.com/us-en/sites/novartis_us/files/cosentyx.pdf')])

q('Which monitoring set is particularly relevant during IL-6 receptor inhibitor treatment?', 'Blood counts, liver enzymes and lipids, with clinical infection assessment despite possible CRP suppression',[
 ('Only serial ANA and RF','These do not provide the required medication safety assessment.'),('Only visual-field testing','Retinal screening is a different drug-specific issue.'),('Only serum urate','This does not assess the main IL-6 treatment toxicities.')],
 'Mechanism affects both adverse effects and biomarker interpretation','**IL-6 blockade can change neutrophil counts, liver tests, lipids and the acute-phase response.**',['Follow the specific product monitoring and dose-adjustment rules.','A low CRP does not exclude serious infection.'], '**Interpret laboratory results with symptoms and examination.**',['Review abdominal symptoms because diverticular complications are relevant to selected patients.','Do not monitor disease activity solely through CRP under pathway blockade.'],[['CBC/LFT/lipids','Safety monitoring'],['CRP','Can be suppressed'],['Infection','Requires clinical vigilance']],[ref('Actemra prescribing information','https://www.gene.com/download/pdf/actemra_prescribing.pdf')])

q('Which vaccine-preventable viral complication is an important consideration before a JAK inhibitor?', 'Herpes zoster',[
 ('Measles only, requiring live MMR during high-dose immune treatment','Live-vaccine timing requires a separate safety plan.'),('Rabies as the routine principal reactivation complication','Rabies is exposure-related rather than the characteristic latent-virus reactivation issue.'),('Poliovirus as the universal expected complication','This is not the principal JAK-associated viral risk.')],
 'Plan prevention before treatment increases risk','**JAK inhibitors are associated with herpes zoster risk.**',['Recombinant zoster vaccine is nonlive and can be indicated in immunosuppressed adults.','Other infection, cardiovascular, malignancy and thrombotic risks also require review.'], '**Use the current local vaccine schedule and product guidance.**',['Prior shingles does not automatically remove the role of vaccination.','Vaccination reduces risk but does not justify ignoring compatible symptoms during treatment.'],[['JAK therapy','Zoster risk'],['Recombinant vaccine','Nonlive prevention option'],['Broader safety','Still requires individual assessment']],[VA,ref('FDA JAK inhibitor safety communication','https://www.fda.gov/drugs/drug-safety-and-availability/fda-requires-warnings-about-increased-risk-serious-heart-related-events-cancer-blood-clots-and-death')])

q('A patient on weekly methotrexate develops AKI during dehydration and then mouth ulcers and falling blood counts. What mechanism should be considered?', 'Reduced methotrexate clearance causing toxicity',[
 ('A guaranteed RA flare because ulcers are always autoimmune','Mucositis and cytopenias after renal impairment raise drug-toxicity concern.'),('A protective fall in methotrexate exposure during AKI','Renal impairment can increase exposure.'),('An isolated urate crystal reaction','This does not explain the marrow and mucosal findings.')],
 'A stable weekly prescription can become unsafe when renal function changes','**Methotrexate clearance is sensitive to kidney function and interacting medications.**',['Dehydration, AKI and altered drug handling can increase toxicity.','Severe mucositis or cytopenia needs urgent assessment.'], '**Withhold further methotrexate pending urgent review.**',['Evaluate dose history, infection, renal function and all interacting medicines.','Specialist rescue and supportive treatment depend on severity.'],[['AKI','Reduced clearance'],['Ulcers/cytopenias','Toxicity warning'],['Action','Urgent medication and clinical review']],[DM],style='clinical_scenario')

q('Which pharmacogenetic pathways are central to thiopurine starting-dose decisions for azathioprine?', 'TPMT and NUDT15',[
 ('HLA-B*58:01 and CYP2C19 only','These do not provide the central thiopurine metabolic risk assessment.'),('HLA-B27 and ACE genotype','These do not guide thiopurine starting doses.'),('MEFV and NLRP3','These are autoinflammatory disease genes rather than the principal thiopurine dosing pathways.')],
 'Identify susceptibility to severe thiopurine myelotoxicity','**Reduced TPMT or NUDT15 function can require substantial dose reduction or an alternative.**',['The CPIC 2025 update addresses both genes and combined intermediate phenotypes.','Genotype-guided dosing does not eliminate all marrow or liver toxicity.'], '**Continue laboratory monitoring even after a reassuring test.**',['Review allopurinol/febuxostat and other relevant interactions.','An unexpected cytopenia still requires prompt evaluation.'],[['TPMT','Thiopurine metabolism'],['NUDT15','Thiopurine nucleotide handling'],['CBC/LFT monitoring','Still necessary']],[ref('CPIC thiopurine guideline: 2025 update, published 2026','https://doi.org/10.1002/cpt.70209')])

q('Which medication requires particular preconception substitution because of established miscarriage and congenital-malformation risk?', 'Mycophenolate mofetil',[
 ('Hydroxychloroquine','This is generally compatible and often continued in lupus pregnancy.'),('Azathioprine in a suitable monitored regimen','This can be a pregnancy-compatible option.'),('Sulfasalazine with appropriate folate','This can be used in pregnancy in an appropriate setting.')],
 'Preserve disease control while removing an incompatible exposure','**Mycophenolate is not suitable for planned pregnancy.**',['Choose an alternative matched to the organ disease.','The recommended contraception and discontinuation intervals must follow current guidance and labeling.'], '**Plan before conception when possible.**',['Coordinate rheumatology and obstetric care.','Do not simply stop all disease-modifying therapy and accept uncontrolled disease.'],[['Mycophenolate','Pregnancy risk'],['Suitable alternatives','Depend on organ disease'],['Goal','Safe exposure plus stable control']],[ref('EULAR reproduction/pregnancy recommendations: 2024 update','https://pubmed.ncbi.nlm.nih.gov/40287311/')])

q('A patient is expected to take glucocorticoids for several months. Which prevention plan is most appropriate?', 'Assess fracture risk and bone health early, with risk-based pharmacological prevention and monitoring',[
 ('Wait for the first fragility fracture before any assessment','Prevention should precede avoidable injury.'),('Assume a normal plain X-ray excludes osteoporosis risk','Plain films do not provide an adequate early fracture-risk assessment.'),('Give identical high-dose calcium/vitamin D to every patient without considering renal or calcium disorders','Supplementation and bone therapy must reflect the patient’s metabolic context.')],
 'Glucocorticoid bone harm can begin early','**Prolonged exposure warrants fracture-risk evaluation.**',['Age, prior fracture, dose, BMD and other risks guide prevention.','Clinical guidance includes risk-based anti-osteoporotic therapy rather than supplements alone for every high-risk patient.'], '**Address exercise, falls, nutrition and medication risks.**',['Plan follow-up and reassess as steroid exposure changes.','Use special caution with calcium/vitamin D disorders such as sarcoidosis.'],[['Risk assessment','Early in prolonged exposure'],['High-risk patient','May need pharmacological bone protection'],['Follow-up','Changes with dose and clinical status']],[ref('ACR glucocorticoid-induced osteoporosis guideline','https://rheumatology.org/glucocorticoid-induced-osteoporosis-guideline')],style='clinical_scenario')

if __name__=='__main__':finalize('Rheumatology',10,'Immunology, Biologics and Treatment Safety','rheum-immunology-safety',rows,28)
